const express=require('express');const bcrypt=require('bcryptjs');const auth=require('../middleware/auth');const betterAuth=require('../middleware/betterAuth');const db=require('../db');const router=express.Router();router.use(auth);
const ROLE_PERMISSIONS={owner:['admin.members','admin.settings','dashboard.read'],admin:['admin.members','admin.settings','dashboard.read'],manager:['dashboard.read'],rep:['dashboard.read'],viewer:['dashboard.read']};
async function membership(req){const{rows}=await db.query(`SELECT organization_id,user_id,role,status FROM organization_members WHERE organization_id=$1 AND user_id=$2 AND status='active'`,[req.user.orgId,req.user.userId]);return rows[0]||null;}function allowed(role,p){return(ROLE_PERMISSIONS[role]||[]).includes(p);}
router.get('/dashboard',async(req,res)=>{try{const m=await membership(req);if(!m||!allowed(m.role,'dashboard.read'))return res.status(403).json({error:{code:'FORBIDDEN',message:'Dashboard access denied'}});const{rows}=await db.query(`SELECT(SELECT COUNT(*)FROM properties WHERE org_id=$1)properties,(SELECT COUNT(*)FROM owners WHERE org_id=$1)owners,(SELECT COUNT(*)FROM leads WHERE org_id=$1)leads,(SELECT COUNT(*)FROM calls WHERE org_id=$1)calls,(SELECT COUNT(*)FROM organization_members WHERE organization_id=$1 AND status='active')members`,[req.user.orgId]);res.json({counts:Object.fromEntries(Object.entries(rows[0]).map(([k,v])=>[k,Number(v)]))});}catch(e){console.error(e);res.status(500).json({error:{code:'DASHBOARD_FAILED',message:'Unable to load dashboard'}});}});
router.get('/members',async(req,res)=>{try{const m=await membership(req);if(!m||!allowed(m.role,'admin.members'))return res.status(403).json({error:{code:'FORBIDDEN',message:'Member administration denied'}});const{rows}=await db.query(`SELECT m.id,u.name,u.email,m.role,m.status,m.created_at FROM organization_members m JOIN users u ON u.id=m.user_id WHERE m.organization_id=$1 ORDER BY u.name,u.email`,[req.user.orgId]);res.json({items:rows});}catch(e){res.status(500).json({error:{code:'MEMBERS_FAILED',message:'Unable to load members'}});}});
router.post('/members',async(req,res)=>{const m=await membership(req);if(!m||!allowed(m.role,'admin.members'))return res.status(403).json({error:{code:'FORBIDDEN',message:'Member administration denied'}});const{name,email,password,role='rep'}=req.body||{};const normalized=String(email||'').trim().toLowerCase();if(!String(name||'').trim()||!normalized||typeof password!=='string'||password.length<8||password.length>128||!['admin','manager','rep','viewer'].includes(role))return res.status(400).json({error:{code:'VALIDATION_ERROR',message:'Name, email, 8-128 character password, and valid role are required'}});const client=await db.pool.connect();try{await client.query('BEGIN');const exists=await client.query('SELECT id FROM users WHERE email=$1',[normalized]);if(exists.rows.length){await client.query('ROLLBACK');return res.status(409).json({error:{code:'EMAIL_EXISTS',message:'Email already exists'}});}const authApi=await betterAuth.getBetterAuth();const hash=await bcrypt.hash(password,12);const user=await client.query('INSERT INTO users(org_id,name,email,password_hash,role) VALUES($1,$2,$3,$4,$5) RETURNING id,name,email,role',[req.user.orgId,String(name).trim(),normalized,hash,role]);try{await authApi.api.signUpEmail({body:{name:String(name).trim(),email:normalized,password}});}catch(authError){await client.query('ROLLBACK');const status=Number(authError?.status)||409;return res.status(status>=400&&status<500?status:409).json({error:{code:'AUTH_ACCOUNT_CREATE_FAILED',message:'Unable to create authentication account for this member'}});}const member=await client.query('INSERT INTO organization_members(organization_id,user_id,role) VALUES($1,$2,$3) RETURNING id,role,status',[req.user.orgId,user.rows[0].id,role]);await client.query('INSERT INTO system_settings(organization_id) VALUES($1) ON CONFLICT(organization_id) DO NOTHING',[req.user.orgId]);await client.query('INSERT INTO audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5,$6)',[req.user.orgId,req.user.userId,'member.created','user',user.rows[0].id,{role,auth:'better_auth'}]);await client.query('COMMIT');res.status(201).json({item:{...user.rows[0],...member.rows[0]}});}catch(e){await client.query('ROLLBACK').catch(()=>{});console.error(e);res.status(500).json({error:{code:'MEMBER_CREATE_FAILED',message:'Unable to create member'}});}finally{client.release();}});
router.get('/settings',async(req,res)=>{try{const m=await membership(req);if(!m||!allowed(m.role,'admin.settings'))return res.status(403).json({error:{code:'FORBIDDEN',message:'Settings administration denied'}});const{rows}=await db.query('SELECT settings,updated_at FROM system_settings WHERE organization_id=$1',[req.user.orgId]);res.json({settings:rows[0]?.settings||{},updatedAt:rows[0]?.updated_at||null});}catch(e){res.status(500).json({error:{code:'SETTINGS_FAILED',message:'Unable to load settings'}});}});
router.patch('/settings',async(req,res)=>{try{const m=await membership(req);if(!m||!allowed(m.role,'admin.settings'))return res.status(403).json({error:{code:'FORBIDDEN',message:'Settings administration denied'}});const settings=req.body?.settings;if(!settings||typeof settings!=='object'||Array.isArray(settings))return res.status(400).json({error:{code:'VALIDATION_ERROR',message:'settings must be an object'}});const result=await db.query(`INSERT INTO system_settings(organization_id,settings,updated_at) VALUES($1,$2,NOW()) ON CONFLICT(organization_id) DO UPDATE SET settings=EXCLUDED.settings,updated_at=NOW() RETURNING settings,updated_at`,[req.user.orgId,settings]);await db.query(`INSERT INTO audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES($1,$2,'settings.updated','organization',$3,$4)`,[req.user.orgId,req.user.userId,req.user.orgId,{keys:Object.keys(settings)}]);res.json({settings:result.rows[0].settings,updatedAt:result.rows[0].updated_at});}catch(e){console.error(e);res.status(500).json({error:{code:'SETTINGS_UPDATE_FAILED',message:'Unable to update settings'}});}});
router.get('/audit',async(req,res)=>{try{const m=await membership(req);if(!m||!allowed(m.role,'admin.settings'))return res.status(403).json({error:{code:'FORBIDDEN',message:'Audit access denied'}});const{rows}=await db.query(`SELECT a.id,a.action,a.entity_type,a.entity_id,a.details,a.created_at,u.name actor_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id WHERE a.organization_id=$1 ORDER BY a.created_at DESC LIMIT 100`,[req.user.orgId]);res.json({items:rows});}catch(e){res.status(500).json({error:{code:'AUDIT_FAILED',message:'Unable to load audit activity'}});}});module.exports=router;
